  n.connect(filter);
  filter.connect(gain);
  gain.connect(dest);
  n.start(time);
  n.stop(time + 0.04);
}

function playBass(ctx: AudioContext, dest: AudioNode, time: number, freq: number, dur: number) {
  const osc = ctx.createOscillator();
  osc.type = 'sawtooth';
  osc.frequency.setValueAtTime(freq, time);
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.setValueAtTime(400, time);
  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.25, time);
  gain.gain.setValueAtTime(0.25, time + dur * 0.7);
  gain.gain.exponentialRampToValueAtTime(0.001, time + dur);
  osc.connect(filter);
  filter.connect(gain);
  gain.connect(dest);
  osc.start(time);
  osc.stop(time + dur);
}

function playSynth(ctx: AudioContext, dest: AudioNode, time: number, freq: number, dur: number) {
  const osc = ctx.createOscillator();
  osc.type = 'square';
  osc.frequency.setValueAtTime(freq, time);
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.setValueAtTime(2000, time);
  filter.frequency.exponentialRampToValueAtTime(800, time + dur);
  const gain = ctx.createGain();
  gain.gain.setValueAtTime(0.08, time);
  gain.gain.setValueAtTime(0.08, time + dur * 0.6);
  gain.gain.exponentialRampToValueAtTime(0.001, time + dur);
  osc.connect(filter);
  filter.connect(gain);
  gain.connect(dest);
  osc.start(time);
  osc.stop(time + dur);
